namespace docking.widgets.table;













using ghidra.docking.settings;
using ghidra.util.table.column;

public class CustomToStringCellRenderer<T> : AbstractGColumnRenderer<T> {

	public class CustomFont
{	public static readonly CustomFont DEFAULT = new();
	public static readonly CustomFont MONOSPACED = new();
	public static readonly CustomFont BOLD = new();

	}

	public static string longToPrefixedHexString(long v) {
		return v < 0 ? "-0x" + Long.toString(-v, 16) : "0x" + Long.toString(v, 16);
	}

	public static string bigIntToPrefixedHexString(BigInteger v) {
		return v.signum() < 0 ? "-0x" + v.negate().toString(16) : "0x" + v.toString(16);
	}

	public static readonly DateFormat TIME_FORMAT_24HMSms = new SimpleDateFormat("HH:mm:ss.SSS");

	public static readonly CustomToStringCellRenderer<Date> TIME_24HMSms =
		new(CustomFont.DEFAULT, typeof(Date),
			(v, s) => v == null ? "<null>" : TIME_FORMAT_24HMSms.format(v), false);
	public static readonly CustomToStringCellRenderer<string> HTML =
		new CustomToStringCellRenderer<string>(CustomFont.DEFAULT, typeof(string),
			(v, s) => v == null ? "<null>" : v, true);
	public static readonly CustomToStringCellRenderer<object> MONO_OBJECT =
		new(CustomFont.MONOSPACED, typeof(object),
			(v, s) => v == null ? "<null>" : v.toString(), false);
	public static readonly CustomToStringCellRenderer<string> MONO_HTML =
		new CustomToStringCellRenderer<string>(CustomFont.MONOSPACED, typeof(string),
			(v, s) => v == null ? "<null>" : v, true);
	public static readonly CustomToStringCellRenderer<Long> MONO_LONG_HEX =
		new(CustomFont.MONOSPACED, typeof(Long),
			(v, s) => v == null ? "<null>" : longToPrefixedHexString(v), false);
	public static readonly CustomToStringCellRenderer<Long> MONO_ULONG_HEX =
		new(CustomFont.MONOSPACED, typeof(Long),
			(v, s) => v == null ? "<null>" : "0x" + Long.toUnsignedString(v, 16), false);
	public static readonly CustomToStringCellRenderer<BigInteger> MONO_BIG_HEX =
		new(CustomFont.MONOSPACED, typeof(BigInteger),
			(v, s) => v == null ? "<null>" : bigIntToPrefixedHexString(v), false);

	private CustomFont customFont;
	private Class<T> cls;
	private BiFunction<T, Settings, string> toString;

	private JPanel panelForSize = new JPanel();
	private BoxLayout layoutForSize = new BoxLayout(panelForSize, BoxLayout.Y_AXIS);

	public CustomToStringCellRenderer(Class<T> cls, BiFunction<T, Settings, string> toString,
			bool enableHtml) : this(null, cls, toString, enableHtml)
    {
	}

	public CustomToStringCellRenderer(CustomFont font, Class<T> cls,
			BiFunction<T, Settings, string> toString, bool enableHtml) {
		this.setHTMLRenderingEnabled(enableHtml);
		this.customFont = font;
		this.cls = cls;
		this.toString = toString;

		panelForSize.setLayout(layoutForSize);
	}

	/* @Override */
	protected Font getDefaultFont() {
		switch (customFont) {
			default:
			case DEFAULT:
				return defaultFont;
			case MONOSPACED:
				return fixedWidthFont;
			case BOLD:
				return boldFont;
		}
	}

	// TODO: Seems the filter model does not heed this....
	/* @Override */
	public string getFilterString(T t, Settings settings) {
		return toString.apply(t, settings);
	}

	/* @Override */
	public Component getTableCellRendererComponent(GTableCellRenderingData data) {
		base.getTableCellRendererComponent(data);
		setText(toString.apply(cls.cast(data.getValue()), data.getColumnSettings()));
		if (isHTMLRenderingEnabled()) {
			setVerticalAlignment(SwingConstants.TOP);
		}
		else {
			setVerticalAlignment(SwingConstants.CENTER);
		}
		return this;
	}

	public int getRowHeight(int colWidth) {
		View v = (View) getClientProperty(BasicHTML.propertyKey);
		if (v == null) {
			return 0;
		}
		v.setSize(colWidth, short.MaxValue);
		return (int) v.getPreferredSpan(View.Y_AXIS);
	}
}
